import {
  RuntimeTaskId,
  type TaskAgentLinkage,
  type RuntimeTaskUsage,
  type TurnTokenUsage,
} from "@t3tools/contracts";
import * as Option from "effect/Option";
import * as Predicate from "effect/Predicate";
import * as Schema from "effect/Schema";

const TokenCount = Schema.Int.check(
  Schema.isGreaterThanOrEqualTo(0),
  Schema.isLessThanOrEqualTo(Number.MAX_SAFE_INTEGER),
);
const decodeTokenCount = Schema.decodeUnknownOption(TokenCount);
const tokenCount = (value: unknown): number | undefined =>
  Option.getOrUndefined(decodeTokenCount(value));

export interface PiMessageUsage {
  readonly inputTokens?: number;
  readonly outputTokens?: number;
  readonly cachedInputTokens?: number;
  readonly cacheCreationTokens?: number;
  readonly complete: boolean;
}

/** Only message_end is authoritative. Pi input excludes both cache categories. */
export function normalizePiMessageUsage(message: Record<string, unknown>): PiMessageUsage {
  const usage = Predicate.isObject(message.usage) ? message.usage : {};
  const input = tokenCount(usage.input);
  const outputTokens = tokenCount(usage.output);
  const cachedInputTokens = tokenCount(usage.cacheRead);
  const cacheCreationTokens = tokenCount(usage.cacheWrite);
  const inputs = [input, cachedInputTokens, cacheCreationTokens];
  const inputTokens = inputs.some((value) => value !== undefined)
    ? tokenCount(inputs.reduce<number>((sum, value) => sum + (value ?? 0), 0))
    : undefined;
  const successful = ["stop", "length", "toolUse"].includes(String(message.stopReason));
  // Pi initializes error/aborted responses with zero usage even if no usage arrived.
  if (!successful && (inputTokens ?? 0) + (outputTokens ?? 0) === 0) return { complete: false };
  return {
    ...(inputTokens !== undefined ? { inputTokens } : {}),
    ...(outputTokens !== undefined ? { outputTokens } : {}),
    ...(cachedInputTokens !== undefined ? { cachedInputTokens } : {}),
    ...(cacheCreationTokens !== undefined ? { cacheCreationTokens } : {}),
    complete:
      successful &&
      inputs.every((value) => value !== undefined) &&
      inputTokens !== undefined &&
      outputTokens !== undefined,
  };
}

/** Missing responses and counters leave known lower bounds, never fabricated zero totals. */
export function completePiTurnUsage(
  messages: ReadonlyArray<PiMessageUsage | undefined>,
  completed: boolean,
  hasSubagents: boolean,
): TurnTokenUsage {
  const totals: {
    inputTokens?: number;
    outputTokens?: number;
    cachedInputTokens?: number;
    cacheCreationTokens?: number;
  } = {};
  let validTotals = true;
  for (const key of [
    "inputTokens",
    "outputTokens",
    "cachedInputTokens",
    "cacheCreationTokens",
  ] as const) {
    const values = messages.flatMap((message) =>
      message?.[key] !== undefined ? [message[key]] : [],
    );
    if (values.length === 0) continue;
    const total = tokenCount(values.reduce((sum, value) => sum + value, 0));
    if (total !== undefined) totals[key] = total;
    else validTotals = false;
  }
  const common = { usageScope: "main_agent", hasSubagents, ...totals } as const;
  if (
    completed &&
    validTotals &&
    messages.length > 0 &&
    messages.every((message) => message?.complete) &&
    totals.inputTokens !== undefined &&
    totals.outputTokens !== undefined
  ) {
    return {
      ...common,
      usageStatus: "complete",
      inputTokens: totals.inputTokens,
      outputTokens: totals.outputTokens,
    };
  }
  return { ...common, usageStatus: Object.keys(totals).length > 0 ? "partial" : "unavailable" };
}

// Shape from Pi's shipped examples/extensions/subagent/index.ts (SubagentDetails).
// This is NOT a generic subagent protocol. Names/arguments alone prove nothing.
const SubagentResult = Schema.Struct({
  agent: Schema.NonEmptyString,
  agentSource: Schema.Literals(["user", "project", "unknown"]),
  task: Schema.String,
  exitCode: Schema.Int,
  messages: Schema.Array(Schema.Unknown),
  stderr: Schema.String,
  usage: Schema.Struct({
    input: TokenCount,
    output: TokenCount,
    cacheRead: TokenCount,
    cacheWrite: TokenCount,
    turns: TokenCount,
  }),
  model: Schema.optional(Schema.String),
  stopReason: Schema.optional(Schema.String),
  errorMessage: Schema.optional(Schema.String),
  step: Schema.optional(Schema.Int.check(Schema.isGreaterThanOrEqualTo(1))),
});
const decodeSubagentResult = Schema.decodeUnknownOption(
  Schema.Struct({
    details: Schema.Struct({
      mode: Schema.Literals(["single", "parallel", "chain"]),
      agentScope: Schema.Literals(["user", "project", "both"]),
      projectAgentsDir: Schema.NullOr(Schema.String),
      results: Schema.Array(SubagentResult),
    }),
  }),
);

export interface PiSubagentSnapshot {
  readonly taskId: RuntimeTaskId;
  readonly linkage: TaskAgentLinkage;
  readonly description: string;
  readonly status: "running" | "completed" | "failed" | "stopped";
  readonly summary?: string;
  readonly typedUsage?: RuntimeTaskUsage;
}

export function normalizePiSubagents(
  toolName: string,
  toolCallId: string,
  result: unknown,
  terminal: boolean,
): ReadonlyArray<PiSubagentSnapshot> {
  if (toolName !== "subagent") return [];
  const decoded = decodeSubagentResult(result);
  if (Option.isNone(decoded)) return [];
  const { mode, results } = decoded.value.details;
  return results.flatMap((entry, index) => {
    const title = entry.agent.trim().slice(0, 200);
    if (!title || (mode === "chain" && entry.step === undefined)) return [];
    // Parallel placeholders are not proof that a process actually started.
    if (!terminal && entry.agentSource === "unknown" && entry.exitCode === -1) return [];
    const inputTokens = tokenCount(
      entry.usage.input + entry.usage.cacheRead + entry.usage.cacheWrite,
    );
    const totalTokens =
      inputTokens !== undefined ? tokenCount(inputTokens + entry.usage.output) : undefined;
    const lastAssistant = entry.messages.findLast(
      (message) => Predicate.isObject(message) && message.role === "assistant",
    );
    const content =
      Predicate.isObject(lastAssistant) && Array.isArray(lastAssistant.content)
        ? lastAssistant.content
        : [];
    const text = content
      .flatMap((part: unknown) =>
        Predicate.isObject(part) && part.type === "text" && typeof part.text === "string"
          ? [part.text]
          : [],
      )
      .join("\n");
    const failed = entry.exitCode !== 0 || entry.stopReason === "error";
    const summary = (terminal && failed ? entry.errorMessage || entry.stderr || text : text)
      .trim()
      .slice(0, 2_000);
    return [
      {
        taskId: RuntimeTaskId.make(`pi:${toolCallId}:${mode === "chain" ? entry.step : index}`),
        linkage: {
          taskType: "subagent",
          title,
          role: title,
          toolUseId: toolCallId,
          ...(entry.model?.trim() ? { model: entry.model.trim() } : {}),
        },
        description: entry.task.trim().slice(0, 400) || title,
        // The example initializes exitCode=0 during streaming; even stopReason=stop
        // can precede another child turn. Only the outer tool end is definitive.
        status: !terminal
          ? "running"
          : entry.stopReason === "aborted"
            ? "stopped"
            : failed
              ? "failed"
              : "completed",
        ...(summary ? { summary } : {}),
        ...(totalTokens !== undefined
          ? {
              typedUsage: {
                totalTokens,
                inputTokens,
                outputTokens: entry.usage.output,
                cachedInputTokens: entry.usage.cacheRead,
              },
            }
          : {}),
      },
    ];
  });
}

